def round_half_to_even(n):
    """
    Round a number to the nearest integer, rounding half to even (also known as round half to nearest even or银行家舍入法)

    :param n: The number to round
    :return: The rounded number
    """
    if n % 1 == 0:
        return int(n)
    elif n > 0:
        decimal_part = n - int(n)
        if decimal_part == 0.5:
            return int(n) + 1 if n % 2 == 1 else int(n)
        else:
            return round(n)
    else:
        decimal_part = n - int(n)
        if decimal_part == -0.5:
            return int(n) - 1 if n % 2 == 0 else int(n)
        else:
            return round(n)

def round_half_to_even(n):
