def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """

    import os
    import subprocess
    from concurrent.futures import ProcessPoolExecutor, as_completed

    def run_command(command, args):
        try:
            process = subprocess.Popen(
                [command, *args], 
                stdout=subprocess.PIPE, 
                stderr=subprocess.PIPE, 
                text=color
            )
            _, stderr = process.communicate()
            process.wait()
            return (process.returncode, stderr)
        except Exception as e:
            return (1, str(e).encode())

    def partition(lst, n):
        return [lst[i:i + n] for i in range(0, len(lst), n)]

    num_partitions = min(target_concurrency, len(varargs))
    partitions = partition(varargs, len(varargs) // num_partitions)

    with ProcessPoolExecutor() as executor:
        futures = {executor.submit(run_command, cmd[0], args + cmd[1:]): args for args in partitions}
        results = []
        for future in as_completed(futures):
            results.append(future.result())

    return sum(returncode for returncode, _ in results), b'\n'.join(stderr for _, stderr in results)

