def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        class TtlCache:
            def __init__(self, maxsize, ttl, timer, typed):
                self.maxsize = maxsize
                self.ttl = ttl
                self.timer = timer
                self.typed = typed
                self.cache = {}
                self.access_times = {}

            def __call__(self, *args, **kwargs):
                key = (args, tuple(kwargs.items())) if typed else (args,)
                if key in self.cache and self.timer() - self.access_times[key] < self.ttl:
                    return self.cache[key]
                result = func(*args, **kwargs)
                if len(self.cache) >= self.maxsize:
                    oldest_key = min(self.access_times, key=self.access_times.get)
                    del self.cache[oldest_key]
                    del self.access_times[oldest_key]
                self.cache[key] = result
                self.access_times[key] = self.timer()
                return result

        return TtlCache(maxsize, ttl, timer, typed)
    return decorator

