            self.ttl = ttl
            self.timer = timer
            self.typed = typed

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = args if not self.typed else (args, tuple(kwargs.items()))
                now = self.timer()

                if key in self.cache:
                    value, time = self.cache[key]
                    if now - time < self.ttl:
                        return value

                result = func(*args, **kwargs)
