@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback
    import inspect

    def get_stack_element(el):
        filename, line, func, text = el
        prefix = ' ' * 4
        if func:
            return prefix + '%s:%s> %s' % (filename, line, text)
        else:
            return prefix + '%s:%s' % (filename, line)

    stack = traceback.extract_stack(limit=max_level)
    path = []
    for i, el in enumerate(reversed(stack)):
        if i >= max_path_level:
            break
        path.append(get_stack_element(el))

    path = path[::-1]
    top = get_stack_element(traceback.extract_tb(e.__traceback__)[-1])
    space = ' ' * 4
    return '\n'.join([space + 'Exception: %s' % e, space + 'In %s' % top] + path)

