def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    if not classes:
        return []

    min_bases = [classes[0]]
    for cls in classes[1:]:
        if not any(issubclass(cls, mb) for mb in min_bases):
            min_bases.append(cls)

    return ordered(min_bases)

def ordered(classes):
    """Return a list of classes in the minimum ordered basis"""

    graph = {cls: set(parents) for cls, parents in classes}
    indegree = {cls: sum(1 for p in parents if p in graph) for cls, parents in graph.items()}

    queue = [cls for cls, deg in indegree.items() if deg == 0]
    result = []

    while queue:
        cls = queue.pop(0)
        result.append(cls)

        for p in graph[cls]:
            indegree[p] -= 1
            if indegree[p] == 0:
                queue.append(p)

    return result

