    for cls in classes:
        # If the class is not already in the dictionary, add it
        if cls not in base_dict:
            base_dict[cls] = True

    # Initialize an empty list to hold the ordered minimum base classes
    ordered_minimal_bases = []

    # Iterate through the list of classes again
