    if hasattr(self, 'fields'):
        for field in self.fields:
            if field.startswith('error_'):
                component = field.split('_')[1]
                if component == 'E':
                    context.error['x'] = {'index': self.fields.index('error_E_low')}
                elif component == 't':
                    context.error['y'] = {'index': self.fields.index('error_t_low')}
                elif component == 'error_E_low':
                    context.error['z'] = {'index': self.fields.index(field)}

