def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    import re
    from .exceptions import ValidationError

    error_messages = []

    def validate_key(key):
        if not isinstance(key, str):
            error_messages.append({repr(key): f'expected string or bytes-like object'})
        elif not re.match(r'^[a-zA-Z0-9_][a-zA-Z0-9_-]*$', key):
            error_messages.append({repr(key): f"Label key '{key}' does not match the regex [...]"})

    def validate_value(value):
        if isinstance(value, dict):
            for val in value.values():
                validate_value(val)
        elif isinstance(value, list):
            for val in value:
                validate_value(val)
        elif not isinstance(value, str):
            error_messages.append({repr(value): f'expected string or bytes-like object'})

    for key, value in labels.items():
        validate_key(key)
        validate_value(value)

    if error_messages:
        raise ValidationError(messages=error_messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    errors = []

    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif not re.match(RGX_LABELKEY, key):
            errors.append({key: "Label key '{}' does not match the regex {}".format(key, RGX_LABELKEY)})

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                elif not re.match(RGX_LABELVALUE, item):
                    errors.append({item: "Label value '{}' does not match the regex {}".format(item, RGX_LABELVALUE)})
        else:
            if not isinstance(value, str):
                errors.append({str(value): 'expected string or bytes-like object'})
            elif not re.match(RGX_LABELVALUE, value):
                errors.append({value: "Label value '{}' does not match the regex {}".format(value, RGX_LABELVALUE)})

    if errors:
        raise ValidationError(**{'messages': errors})

