    return manifest_dict

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field in observer_schema:
        if field in response:
            if field not in last_applied_manifest:
                last_applied_manifest.append(field)
            if isinstance(response[field], list):
                update_last_applied_manifest_list_from_resp last_applied_manifest[field], observer_schema[field], response[field])
            elif isinstance(response[field], dict):
                update_last_applied_manifest_dict_from_resp last_applied_manifest[field], observer_schema[field], response[field])

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for item in observer_schema:
        if item not in last_applied_manifest:
            last_applied_manifest.append(item)
    for item in response:
        if item not in last_applied_manifest:
            last_applied_manifest.append(item)
    for sub_schema, sub_response in zip(observer_schema, response):
        if isinstance(sub_schema, dict) and isinstance(sub_response, dict):
            update_last_applied_manifest_dict_from_resp(sub_schema, sub_response)

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial `last_applied_manifest`
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial `last_applied_manifest` being
            updated
        observer_schema (list): partial `observer_schema`
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present.

    """
    for item in response:
        for key, value in item.items():
            if key not in last_applied_manifest:
                last_applied_manifest.append({key: value})
            else:
                if isinstance(last_applied_manifest[key], list) and isinstance(value, dict):
                    update_last_applied_manifest_list_from_resp(last_applied_manifest[key], observer_schema, [value])
                elif value != last_applied_manifest[key]:
                    last_applied_manifest[key] = value

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
