    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for field, value in observer_schema.items():
        if field in response:
            if isinstance(value, dict):
                if isinstance(response[field], dict):
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest.get(field, {}), value, response[field]
                    )
                    last_applied_manifest[field] = last_applied_manifest.get(field, {})
            else:
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = response[field]
        else:
            raise KeyError(f"Observed field '{field}' not present in Kubernetes response")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if not resource.get("observer_schema"):
            default_schema = {
                "type": "object",
                "properties": {
                    "status": {
                        "type": "object",
                        "properties": {
                            "phase": {
                                "type": "string"
                            }
                        }
                    }
                }
            }
            resource["observer_schema"] = default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schemas = {}

    for resource in app.spec.manifest:
        if 'observer_schema' not in resource:
            # Create a default schema based on the resource definition
            default_schema = {
                "apiVersion": resource.get("apiVersion", ""),
                "kind": resource.get("kind", ""),
                "metadata": {},
                "spec": resource.get("spec", {})
            }
            default_schemas[resource.get("name")] = default_schema

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if "observer_schema" not in resource:
            resource["observer_schema"] = "default"

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import hashlib
    import json

    def hash_file(file_path):
        hasher = hashlib.sha256()
        with open(file_path, 'rb') as f:
            buf = f.read(65536)
            while len(buf) > 0:
                hasher.update(buf)
                buf = f.read(65536)
        return hasher.hexdigest()

    def get_manifest(root):
        manifest_path = os.path.join(root, 'manifest.json')
        with open(manifest_path, 'r') as f:
            return json.load(f)

    def validate_object(path, manifest):
        if not os.path.isdir(path):
            return False

        for key, value in manifest.items():
            if not os.path.isfile(value['path']):
                return False

            actual_hash = hash_file(value['path'])
            if actual_hash != value['checksum']:
                return False

        return True

    def validate_structure(root):
        if not os.path.isfile(os.path.join(root, 'manifest.json')):
            return False

        manifest = get_manifest(root)
        return validate_object(root, manifest)

    if not os.path.exists(path):
        return False

    if os.path.isfile(path):
        manifest = get_manifest(os.path.dirname(path))
        return validate_object(os.path.dirname(path), manifest)

    return validate_structure(path)

