def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    missing_digests = set(manifest_files.digests_required()) - set(manifest_files.digests_present())
    if missing_digests:
        raise MissingDigestsError("Missing digests: " + ", ".join(missing_digests))

    unused_digests = set(manifest_files.digests_present()) - set(digests_used)
    if unused_digests:
        raise UnusedDigestsError("Unused digests: " + ", ".join(unused_digests))

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    missing_digests = set(manifest_files) - digests_used
    if missing_digests:
        raise MissingDigestError(f"Missing digests: {', '.join(missing_digests)}")

    extra_digests = digests_used - manifest_files
    if extra_digests:
        raise ExtraDigestError(f"Extra digests: {', '.join(extra_digests)}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            for line in file:
                digest, path = line.strip().split()
                if digest not in digests_used:
                    raise DigestNotFoundError(f"Digest {digest} in manifest file {manifest_file} is not used.")
                if path not in self.files:
                    raise FilePathNotFoundError(f"File path {path} in manifest file {manifest_file} does not exist in the archive.")

