def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    if self.version != prior.version - 1:
        raise ValueError("Invalid prior version. Expected version {} but got version {}.".format(self.version - 1, prior.version))

    for item in self.items:
        if item.id not in prior.items:
            raise ValueError("Missing item in prior version: {}".format(item.id))

    for key, value in self.attributes.items():
        if key not in prior.attributes:
            raise ValueError("Missing attribute in prior version: {}".format(key))

    if self.strict:
        for item in prior.items:
            if item.id not in self.items:
                raise ValueError("Extra item in prior version: {}".format(item.id))

        for key, value in prior.attributes.items():
            if key not in self.attributes:
                raise ValueError("Extra attribute in prior version: {}".format(key))

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check if the prior object is an instance of InventoryValidator
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The input variable prior is expected to be an InventoryValidator object.")

    # Compare the version numbers of the two inventories
    if self.version < prior.version:
        raise ValueError("The inventory object to be validated is not a valid prior version.")

    # Check if all items in the prior inventory exist in the current inventory
    for item_id, item in prior.items.items():
        if item_id not in self.items:
            raise ValueError("The inventory object to be validated is missing items from the prior version.")

    # Check if all item data in the prior inventory matches the current inventory
    for item_id, item in prior.items.items():
        current_item = self.items[item_id]
        if item != current_item:
            raise ValueError("The inventory object to be validated has different item data than the prior version.")

    # If all checks pass, the current inventory object is a valid prior version
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    for item in inventory[version]['items']:
        logical_path = item['logical_path']
        content_files = item['content_files']
        if logical_path in path_map:
            path_map[logical_path].update(content_files)
