    """Extira do conteúdo de <issue>xxxx</issue>, os valores number e suppl."""
    number = None
    suppl = None

    content = issue.strip()
    if content:
        if 'suppl' in content.lower():
            suppl = 'suppl'
            number_parts = []
            for part in content.split():
                if part.isnumeric():
                    number_parts.append(part)
                elif part.lower().startswith('spe'):
                    number_parts.append(part[3:] if part[3:].isnumeric() else part[-1:])
            if number_parts:
                number_parts.sort(key=lambda x: int(x if x.isnumeric() else x[1:]))
                number = int(number_parts[0])

    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    return '\n'.join(self._pretty(indent, debug))

def _pretty(self, indent, debug):
    """
    Generator to produce the pretty-formatted representation of this element.
    """
    lines = []
    space = ' ' * indent
    lines.append(f"{space}{self.__class__.__name__}:")
    for key, value in self.__dict__.items():
        if key.startswith('_'):
            continue
        if isinstance(value, list):
            for item in value:
                if isinstance(item, AbstractElement):
                    lines.extend(item._pretty(indent + 4, debug))
                else:
                    lines.append(f"{space}  {key}: {repr(value)}")
        elif isinstance(value, AbstractElement):
            lines.extend(value._pretty(indent + 4, debug))
        else:
            lines.append(f"{space}  {key}: {repr(value)}")
    return lines

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    new_args = []
    for expr in args:
        if expr.is_and():
            if expr.args[0].is_or() and expr.args[0].args[0] == expr.args[1]:
                new_args.append(expr.args[0].args[1])
            elif expr.args[0].is_and() and expr.args[0].args[1] == expr.args[1]:
                new_args.append(expr.args[0].args[0])
            else:
                new_args.append(expr)
        elif expr.is_or():
            if expr.args[0].is_and() and expr.args[0].args[0] == expr.args[1]:
                new_args.append(expr.args[0].args[1])
            elif expr.args[0].is_and() and expr.args[0].args[1] == expr.args[1]:
                new_args.append(expr.args[0].args[0])
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

