            stderr = subprocess.DEVNULL
        else:
            stderr = None

        process = subprocess.run(args, cwd=cwd, env=env, text=True, capture_output=True, check=True, stdin=subprocess.DEVNULL, stderr=stderr, stdout=subprocess.PIPE)

        if verbose:
            print(f"Command output: {process.stdout}")

        return process.stdout

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess

    if not isinstance(commands, list):
        commands = [commands]

    if not args:
        args = []

    for command in commands:
        if verbose:
            print(f"Running command: {command} with args: {args}")

        try:
            process = subprocess.Popen(
                [command] + args,
                cwd=cwd,
                env=env,
                stderr=subprocess.STDOUT if hide_stderr else subprocess.STDOUT
            )
            exit_code = process.wait()

            if exit_code != 0:
                if verbose:
                    print(f"Command {command} exited with code {exit_code}")
                raise subprocess.CalledProcessError(exit_code, command)
        except Exception as e:
            if verbose:
                print(f"Error running command {command}: {e}")
            raise

