def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser instance, give each requested action's subparser a shot at parsing all arguments. This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of arguments, a list of remaining arguments not claimed by any subparser).'''
    parsed_results = {}
    remaining_arguments = unparsed_arguments[:]
    for name, subparser in subparsers.items():
        # Create an argument parser for the current subparser and add it to the main parser
        parser = argparse.ArgumentParser(add_help=False, parents=[subparser])
        try:
            # Attempt to parse the arguments
            namespace, remaining = parser.parse_known_args(remaining_arguments)
            parsed_results[name] = namespace
            # Remove the parsed arguments from the remaining list
            remaining_arguments = [arg for arg in remaining_arguments if arg not in sys.argv[1:remaining + 1]]
        except (argparse.ArgumentTypeError, argparse.ArgumentError):
            # If parsing fails, skip to the next subparser
            pass
    return parsed_results, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_namespaces = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        namespace, remaining = subparser.parse_known_args(remaining_arguments)
        parsed_namespaces[subparser_name] = namespace
        remaining_arguments = [arg for arg in remaining if arg[:2] != '--']

    return parsed_namespaces, remaining_arguments

