        parser = argparse.ArgumentParser(add_help=False, parents=[subparser])
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_namespaces[subparser_name] = namespace
            unparsed_arguments = remaining
        except argparse.ArgumentError:
            continue

    return parsed_namespaces, unparsed_arguments

