def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''

    from argparse import ArgumentParser, _ActionsContainer, _SubParsersAction, _Namespace

    def parse_nested_namespace(ns):
        if isinstance(ns, _Namespace):
            return {k: parse_nested_namespace(v) for k, v in ns.__dict__.items() if not k.startswith('_')}
        elif isinstance(ns, dict):
            return {k: parse_nested_namespace(v) for k, v in ns.items()}
        else:
            return ns

    parser = ArgumentParser(add_help=False, argument_default=None)
    subparsers = parser.add_subparsers(dest='subcommand')

    def add_parser(name, **kwargs):
        return subparsers.add_parser(name, add_help=False, parents=[parser], **kwargs)

    global_namespace = parser.parse_args(unparsed_arguments)
    parsed_arguments = {global_namespace.subcommand: global_namespace}

    for parser_name, parser in subparsers._name_parser_map.items():
        arg_groups = [group for action in parser._actions if action.mutations and isinstance(action, _ActionsContainer) for group in action._groups]
        for group in arg_groups:
            _parser = argparse.ArgumentParser.add_argument_group(group.title)
            _parser._groups.append(group)
        parsed_arguments[parser_name] = parser.parse_args(unparsed_arguments)

    for key, value in parsed_arguments.items():
        parsed_arguments[key] = parse_nested_namespace(value)

    return parsed_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser instance, give each requested action's subparser a shot at parsing all arguments. This allows common arguments like "--repository" to be shared across multiple subparsers. Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of arguments, a list of remaining arguments not claimed by any subparser).'''

    parsed_args = {}
    remaining_args = []

    for subparser_name, subparser in subparsers.items():
        args, remaining = subparser.parse_known_args(unparsed_arguments)
        parsed_args[subparser_name] = args
        unparsed_arguments = remaining

    return parsed_args, unparsed_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_args = {}
    remaining_args = []

    for subparser_name, parser in subparsers.items():
        namespace, _, unparsed = parser.parse_known_args(unparsed_arguments)
        if unparsed:
            parsed_args[subparser_name] = namespace
            unparsed_arguments = unparsed
        else:
            remaining_args.extend(unparsed_arguments)
            unparsed_arguments = []

    return parsed_args, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if 'K' in size:
        return int(float(size[:-1]) * 1000)
    elif 'M' in size:
        return int(float(size[:-1]) * 1000000)
    elif 'G' in size:
        return int(float(size[:-1]) * 1073741824)
    elif 'T' in size:
        return int(float(size[:-1]) * 1099511627776)
    else:
        return int(size)

