def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        raise ValueError("Number must be non-negative")

    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    result = []
    base = len(alphabet)

    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding is not None:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")

    result = []

    if number == 0:
        return alphabet[0]

    while number > 0:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    result = result[::-1]

    if padding is not None and len(result) < padding:
        result = [alphabet[0]] * (padding - len(result)) + result

    return ''.join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        raise ValueError("Number must be non-negative")

    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    base = len(alphabet)
    if base > len(set(alphabet)):
        raise ValueError("Alphabet must contain unique characters")

    if padding is None:
        padding = 0
    elif padding < 0:
        raise ValueError("Padding must be non-negative")

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    result = result[::-1]
    if padding > len(result):
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(result)

