    temp_dir = Path(tmp_path) / Path(archive_path).stem
    temp_dir.mkdir(parents=True, exist_ok=True)

    if filename:
        archive_path = temp_dir / filename

    if archive_path.suffix == ".zip":
        subprocess.run(["unzip", archive_path, "-d", temp_dir], check=True)
    elif archive_path.suffix == ".tar.gz":
        subprocess.run(["tar", "-xzf", archive_path, "-C", temp_dir], check=True)
    elif archive_path.suffix == ".tar.bz2":
        subprocess.run(["tar", "-xjf", archive_path, "-C", temp_dir], check=True)
    else:
        raise ValueError(f"Unsupported archive format: {archive_path.suffix}")

    return str(temp_dir / "repo")

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    result = subprocess.run(['git', 'status', '--ignored', '--porcelain'], stdout=subprocess.PIPE)
