def parse_frequency(frequency):
    ''' Parses a given frequency string into a datetime.timedelta instance or None, handling special cases like "always". Raises ValueError if the frequency cannot be parsed. '''
    if frequency is None or frequency == "always":
        return None
    frequency = frequency.strip().lower()
    for unit in ['week', 'days', 'hour', 'minutes', 'second']:
        if frequency.endswith(unit):
            try:
                num = float(frequency[:-len(unit)])
                if unit == 'week':
                    return datetime.timedelta(weeks=num)
                elif unit == 'days':
                    return datetime.timedelta(days=num)
                elif unit == 'hour':
                    return datetime.timedelta(hours=num)
                elif unit == 'minutes':
                    return datetime.timedelta(minutes=num)
                elif unit == 'second':
                    return datetime.timedelta(seconds=num)
            except ValueError:
                continue
    raise ValueError(f"Invalid frequency format: {frequency}")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    units = {
        'second': 'seconds',
        'minute': 'minutes',
        'hour': 'hours',
        'day': 'days',
        'week': 'weeks',
        'month': 'months',
        'year': 'years'
    }

    try:
        number, unit = frequency.split()
        number = int(number)
        unit = unit.strip('s')  # handle plural forms
        if unit in units:
            return getattr(datetime.timedelta, units[unit])(**{units[unit]: number})
        else:
            raise ValueError("Unsupported time unit: " + unit)
    except (ValueError, AttributeError):
        raise ValueError("Invalid frequency format: " + frequency)

from datetime import timedelta

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
    except (ValueError, AttributeError):
        raise ValueError("Invalid frequency format")

    if unit == "seconds":
        return timedelta(seconds=number)
    elif unit == "minutes":
        return timedelta(minutes=number)
    elif unit == "hours":
        return timedelta(hours=number)
    elif unit == "days":
        return timedelta(days=number)
    elif unit == "weeks":
        return timedelta(weeks=number)
    elif unit == "months":
        # Approximate: assuming 30 days per month
        return timedelta(days=number * 30)
    elif unit == "years":
        # Approximate: assuming 365 days per year
        return timedelta(days=number * 365)
    else:
        raise ValueError("Unsupported time unit")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency.lower() == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    num = parts[0]
    unit = parts[1].lower()

    try:
        num = int(num)
    except ValueError:
        raise ValueError("Invalid frequency format")

    if unit == "seconds":
        return datetime.timedelta(seconds=num)
    elif unit == "minutes":
        return datetime.timedelta(minutes=num)
    elif unit == "hours":
        return datetime.timedelta(hours=num)
    elif unit == "days":
        return datetime.timedelta(days=num)
    elif unit == "weeks":
        return datetime.timedelta(weeks=num)
    elif unit == "months":
        raise ValueError("Invalid frequency unit: months")
    elif unit == "years":
        raise ValueError("Invalid frequency unit: years")
    else:
        raise ValueError("Invalid frequency unit")

