def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    if roots is None:
        roots = set()

    children = set(graph.subjects(prop))
    parents = set(graph.objects(None, prop))

    for child in children:
        if child not in parents:
            roots.add(child)

    for parent in parents:
        if parent in children:
            if parent in roots:
                roots.remove(parent)

    return roots

