def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    from configparser import ConfigParser
    import os
    import threading

    config_dict = {}
    log_records = []

    def load_and_validate(filename, config_dict, log_records):
        parser = ConfigParser()
        try:
            parser.read(filename)
            # Validate the configuration here
            config_dict[filename] = parser
        except Exception as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, name='config_loader', pathname=filename, lineno=0, msg=str(e), args=None, exc_info=None))

    threads = []
    for filename in config_filenames:
        thread = threading.Thread(target=load_and_validate, args=(filename, config_dict, log_records))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    if overrides:
        for section, items in overrides.items():
            if section in config_dict:
                for key, value in items.items():
                    config_dict[section][key] = value

    if resolve_env:
        for section in config_dict:
            for key, value in config_dict[section].items():
                if value.startswith('$'):
                    config_dict[section][key] = os.environ.get(value[1:], value)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    from configparser import ConfigParser
    from collections import OrderedDict

    if overrides is None:
        overrides = {}

    config_results = {}
    log_records = []

    for config_filename in config_filenames:
        if not os.path.isfile(config_filename):
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Configuration file not found: {config_filename}"))
            continue

        try:
            if config_filename.endswith('.json'):
                with open(config_filename) as f:
                    config_data = json.load(f)
            elif config_filename.endswith('.ini'):
                config_data = ConfigParser(dict_type=OrderedDict)
                config_data.read(config_filename, encoding='utf-8')
                config_data = dict(config_data.items())
            else:
                log_records.append(logging.LogRecord(level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Unsupported configuration file format: {config_filename}"))
                continue

            config_data.update(overrides)
            for key, value in config_data.items():
                if resolve_env and isinstance(value, str) and value.startswith('${'):
                    env_var = value[2:-1]
                    if env_var in os.environ:
                        config_data[key] = os.environ[env_var]
                    else:
                        log_records.append(logging.LogRecord(level=logging.WARNING, pathname=config_filename, lineno=0, msg=f"Environment variable not found: {env_var}"))

            config_results[config_filename] = config_data
        except Exception as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=config_filename, lineno=0, msg=f"Error parsing configuration file: {config_filename}, error: {str(e)}"))

    return config_results, log_records

