def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"{candidate.__class__} does not claim to provide the interface {iface}")

    methods = {name: getattr(iface, name) for name in iface.names(x=True, r=False) if callable(getattr(iface, name))}
    candidate_methods = {name: getattr(candidate, name) for name in methods if hasattr(candidate, name)}

    for name, method in methods.items():
        if name not in candidate_methods:
            errors.append(f"{candidate.__class__} does not define the method {name}")
        else:
            candidate_method = candidate_methods[name]
            method_signature = interface.getSignature(method)
            candidate_method_signature = interface.getSignature(candidate_method)
            if method_signature != candidate_method_signature:
                errors.append(f"Method {name} has incorrect signature in {candidate.__class__}")

    attributes = {name: getattr(iface, name) for name in iface.names(x=False, r=False)}
    candidate_attributes = {name: getattr(candidate, name) for name in attributes if hasattr(candidate, name)}

    for name, attribute in attributes.items():
        if name not in candidate_attributes:
            errors.append(f"{candidate.__class__} does not define the attribute {name}")

    if errors:
        if len(errors) == 1:
            raise interface.Invalid(errors[0])
        else:
            raise interface.Invalid(", ".join(errors))

    return True

