            current_tag = ['@']
        elif current_tag:
            current_tag.append(char)
        else:
            result.append(char)

    if current_tag:
        tags.add(''.join(current_tag))

    result_text = ''.join(result)

    if replacer:
        result_text = ''.join(replacer(tag) if tag in tags else tag for tag in result_text.split())

    return tags, result_text

