import json
from xml.etree import ElementTree as ET
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Attempt to parse as JSON
        data = json.loads(document)
        # Check if the JSON data contains the expected keys
        if 'subject' in data and 'links' in data:
            return data
        else:
            raise ValueError("Invalid JSON structure for Diaspora webfinger")
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XRD
        try:
            root = ET.fromstring(document)
            subject = root.find('{*}Subject', nsmap={'*': 'http://webfinger.net/profile/card'})
            if subject is None or subject.text is None:
                raise ValueError("Invalid XRD structure for Diaspora webfinger")
            links = root.findall('{*}Link', nsmap={'*': 'http://webfinger.net/profile/card'})
            result = {'subject': subject.text, 'links': [link.attrib for link in links]}
            return result
        except ET.ParseError:
            raise ValueError("Invalid XRD document for Diaspora webfinger")

